  function projectAvaDraftDocumentRowStatus(input2) {
    if (input2.uploadStatus === "uploading") return { state: "UPLOADING", label: "Enviando\u2026", requiresHumanSelection: false, terminal: false };
    if (input2.uploadStatus === "failed") return { state: "FAILED", label: "Falha no envio", requiresHumanSelection: true, terminal: true };
    if (input2.classificationSource === "HUMAN_CONFIRMED") return { state: "HUMAN_CLASSIFIED", label: "Classifica\xE7\xE3o humana", requiresHumanSelection: false, terminal: true };
    if (input2.classificationSource === "AVA_AUTO_ACCEPTED" || input2.automationDisposition === "AUTO_ACCEPT") return { state: "AUTO_ACCEPTED", label: "Identificado automaticamente", requiresHumanSelection: false, terminal: true };
    if (input2.automationDisposition === "HUMAN_CORRECTED") return { state: "HUMAN_CLASSIFIED", label: "Classifica\xE7\xE3o humana", requiresHumanSelection: false, terminal: true };
    if (input2.automationDisposition === "UNMAPPED_DOCUMENT") return { state: "UNMAPPED_DOCUMENT", label: "Tipo documental n\xE3o cadastrado", requiresHumanSelection: true, terminal: true };
    if (input2.automationDisposition === "REJECTED") return { state: "UNMAPPED_DOCUMENT", label: "Tipo documental n\xE3o cadastrado", requiresHumanSelection: true, terminal: true };
    if (input2.automationDisposition === "HUMAN_REVIEW_REQUIRED") return { state: "REVIEW_REQUIRED", label: "Revis\xE3o necess\xE1ria", requiresHumanSelection: true, terminal: true };
    if (input2.analysisStatus === "FAILED" || input2.analysisStatus === "INVALID_OUTPUT") return { state: "FAILED", label: "Falha na an\xE1lise", requiresHumanSelection: true, terminal: true };
    if (input2.analysisStatus === "COMPLETED") {
      return input2.automationEnabled ? { state: "PROCESSING", label: "Finalizando identifica\xE7\xE3o com IA\u2026", requiresHumanSelection: false, terminal: false } : { state: "QUEUED", label: "An\xE1lise salva \xB7 aguardando finaliza\xE7\xE3o documental", requiresHumanSelection: false, terminal: false };
    }
    if (input2.analysisStatus === "PROCESSING") {
      return { state: "PROCESSING", label: "\u26A1 AVA est\xE1 analisando este documento\u2026", requiresHumanSelection: false, terminal: false };
    }
    if (input2.admissionState === "SUSPENDED" && input2.persisted) return { state: "SUSPENDED", label: "Fila preservada \xB7 processamento suspenso", requiresHumanSelection: true, terminal: false };
    if (input2.analysisStatus === "REQUESTED") return { state: "QUEUED", label: "Na fila para an\xE1lise da AVA", requiresHumanSelection: !input2.automationEnabled, terminal: false };
    if (!input2.automationEnabled && input2.persisted) return { state: "QUEUED", label: "\u26A1 Na fila de processamento da AVA\u2026", requiresHumanSelection: true, terminal: false };
    if (input2.persisted && input2.automationEnabled) return { state: "QUEUED", label: "Aguardando an\xE1lise da AVA", requiresHumanSelection: false, terminal: false };
    return { state: "RECEIVED", label: "Documento recebido", requiresHumanSelection: false, terminal: false };
  }

